export type ShareInvitation = { "share": SessionShare; "token": (ShareToken) | (null); "serverTime": Timestamp };
export type ShareList = { "items": (SessionShare)[]; "nextPageToken": (string) | (null); "serverTime": Timestamp };
export type SharedSession = { "share": SessionShare; "session": Session; "ownerName": string; "agentName": string; "projectName": string; "nodeName": string; "nodeOnline": boolean; "requests": (InteractionRequest)[]; "serverTime": Timestamp };
export type SharedCommand = ({ "action": "send"; "payload": { "expectedTurnId": Id; "text": Prompt; "mode": "send" | "queue"; "capabilityRevision": Sequence } }) | ({ "action": "cancel"; "payload": CancelTurn }) | ({ "action": "respond"; "requestId": Id; "payload": RespondRequest });
export type ShareActivity = { "items": ({ "id": Id; "shareId": Id; "actorName": string; "action": "send" | "cancel" | "respond"; "state": string; "createdAt": Timestamp })[]; "nextPageToken": (string) | (null) };
export type UserProfile = { "displayName": string; "avatarBase64": (string) | (null); "revision": number };
export type UpdateUserProfile = { "displayName": string; "avatarBase64"?: (string) | (null); "revision": number };
export type ProjectHistory = { "nodeId": Id; "projectId": Id; "agentId": Id; "capabilityRevision": Sequence; "request": Record<string, unknown> };
